import utest.*

object JwkTest extends TestSuite:

  // test vectors generated by a known-working python implementation
  val privateKeyPem =
    """|-----BEGIN PRIVATE KEY-----
       |MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgNtPF/mdb5xHs/yUl
       |THYECvtG4sFsxOw3Yo4qNGE72SihRANCAASjJPNRC2FvxgxTfJwNrZSHlnQZ651s
       |FW9XbYm4XNHPFi9RypybB48GvqkZt9KyL7mRTQmRgvQY5jmNMFCaxOOB
       |-----END PRIVATE KEY-----
       |""".stripMargin

  val publicKeyPem =
    """|-----BEGIN PUBLIC KEY-----
       |MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEoyTzUQthb8YMU3ycDa2Uh5Z0Geud
       |bBVvV22JuFzRzxYvUcqcmwePBr6pGbfSsi+5kU0JkYL0GOY5jTBQmsTjgQ==
       |-----END PUBLIC KEY-----
       |""".stripMargin

  val expectedJwk = ujson.read(
    """
    {
      "keys": [
        {
          "alg": "ES256",
          "crv": "P-256",
          "kid": "b9745db29897ee14",
          "kty": "EC",
          "use": "sig",
          "x": "oyTzUQthb8YMU3ycDa2Uh5Z0GeudbBVvV22JuFzRzxY",
          "y": "L1HKnJsHjwa-qRm30rIvuZFNCZGC9BjmOY0wUJrE44E"
        }
      ]
    }
    """
  )

  // x: 73792280122720911594079467075857548128027121252577777117633181380433809624854
  // y: 21403216870500815829706950962568896468805281374870948182606691205673879135105

  val privateKeyBytes = java.util.Base64.getDecoder.decode(
    privateKeyPem
      .replace("-----BEGIN PRIVATE KEY-----", "")
      .replace("-----END PRIVATE KEY-----", "")
      .replaceAll("\\s", "")
  )
  val privateKeySpec = new java.security.spec.PKCS8EncodedKeySpec(privateKeyBytes)
  val keyFactory = java.security.KeyFactory.getInstance("EC")
  val privateKey = keyFactory.generatePrivate(privateKeySpec)

  val publicKeyBytes = java.util.Base64.getDecoder.decode(
    publicKeyPem
      .replace("-----BEGIN PUBLIC KEY-----", "")
      .replace("-----END PUBLIC KEY-----", "")
      .replaceAll("\\s", "")
  )
  val publicKeySpec = new java.security.spec.X509EncodedKeySpec(publicKeyBytes)
  val publicKey = keyFactory.generatePublic(publicKeySpec)

  println("x: " + publicKey.asInstanceOf[java.security.interfaces.ECPublicKey].getW().getAffineX())
  println("y: " + publicKey.asInstanceOf[java.security.interfaces.ECPublicKey].getW().getAffineY())

  val tests = Tests:
    test("jwkFromKey"):
      val jwk = oauth2.jwt.jwkFromKey(publicKey).value.toSeq.sortBy(_._1)
      val expected = expectedJwk("keys")(0).obj.toSeq.sortBy(_._1)

      println(jwk)
      println(expected)

      for (l, r) <- jwk.zip(expected) do
        assert(l == r)

    test("jwt"):
      val claims = ujson.Obj(
        "sub" -> "1234567890",
        "name" -> "John Doe",
        "admin" -> true
      )

      val jwt = oauth2.jwt.signJwt(
        claims,
        privateKey.asInstanceOf[java.security.interfaces.ECPrivateKey],
        publicKey.asInstanceOf[java.security.interfaces.ECPublicKey]
      )
      println(jwt)

      val verified = oauth2.jwt.verifyJwt(jwt, publicKey.asInstanceOf[java.security.interfaces.ECPublicKey])
      assert(verified.isDefined)
      assert(verified.get == claims)

      val forged = jwt.substring(0, jwt.lastIndexOf('.')) + ".forgedsignature"
      val verifiedForged = oauth2.jwt.verifyJwt(forged, publicKey.asInstanceOf[java.security.interfaces.ECPublicKey])
      assert(verifiedForged.isEmpty)

      val bitFlipped = jwt.substring(0, jwt.indexOf('.') + 1) + {
        val payload = jwt.substring(jwt.indexOf('.') + 1, jwt.lastIndexOf('.'))
        val decoded = java.util.Base64.getDecoder.decode(payload)
        val modified = decoded.updated(0, (decoded(0) ^ 1).toByte)
        java.util.Base64.getEncoder.withoutPadding.encodeToString(modified)
      } + jwt.substring(jwt.lastIndexOf('.'))
      val verifiedBitFlipped = oauth2.jwt.verifyJwt(bitFlipped, publicKey.asInstanceOf[java.security.interfaces.ECPublicKey])
      assert(verifiedBitFlipped.isEmpty)

      // also, use a site like https://jwt.io/ to verify the signature using the public key, and check that the signature is correct
